def desconto(de, por):
    if de > por and de > 0:
        return int(round((1 - (por / de)) * 100))
    return 0

def brl(v):
    return ("%.2f" % v).replace(".", ",")

def card(p, idx):
    d = desconto(p["de"], p["pc"])
    tem_vs = "vs" in p and len(p.get("vs", [])) > 1
    badge = ""
    if d > 0:
        badge = "<span class='bd'>-" + str(d) + "% OFF</span>"
    de_html = ""
    if d > 0:
        de_html = "<div class='pde'>De R$ " + brl(p["de"]) + "</div>"
    if p["e"] <= 10:
        est = "<div class='est esc'>Apenas " + str(int(p["e"])) + " unid.</div>"
    else:
        est = "<div class='est'>Disponivel</div>"

    opts = ""
    if tem_vs:
        for i, v in enumerate(p["vs"]):
            chk = "checked" if i == 0 else ""
            nm = v["v"].replace("'", "")
            opts = opts + "<input type='radio' name='v" + str(idx) + "' id='q" + str(idx) + "_" + str(i) + "' value='" + v["ean"] + "' data-nm='" + nm + "' data-pc='" + brl(v["pc"]) + "' " + chk + " onchange='mudaOp(" + str(idx) + ")'><label class='op' for='q" + str(idx) + "_" + str(i) + "'>" + v["v"] + "</label>"

    ean_pad = p["ean"] if "ean" in p else ""
    nm_pad = p["n"].replace("'", "").replace('"', "")
    if tem_vs:
        ean_pad = p["vs"][0]["ean"]
        nm_pad = (p["n"] + " - " + p["vs"][0]["v"]).replace("'", "")

    foto_url = CDN_IMG + ean_pad

    return (
        "<article class='card' data-i='" + str(idx) + "'>"
        "<div class='ctop'>" + badge + "</div>"
        "<div class='imgb'><img class='fot' src='" + foto_url + "' alt='" + nm_pad + "' loading='lazy'"
        " onerror='this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';'>"
        "<div class='fb' style='display:none'><span class='ic'>&#128138;</span><span class='fbn'>" + p["f"] + "</span></div></div>"
        "<div class='cb'>"
        "<h3 class='nm'>" + p["n"] + "</h3>"
        "<div class='fl'>" + p["f"] + "</div>"
        "<div class='pcs'>" + de_html +
        "<div class='pp'><span>R$</span> <span id='pc" + str(idx) + "'>" + brl(p["pc"]) + "</span></div>" + est + "</div>" +
        (("<div class='sv'>Escolha:</div><div class='ops'>" + opts + "</div>") if tem_vs else "") +
        "<input type='hidden' id='en" + str(idx) + "' value='" + ean_pad + "'>"
        "<input type='hidden' id='nn" + str(idx) + "' value='" + nm_pad + "'>"
        "<button class='btnadd' onclick='addSac(" + str(idx) + ")'>ADICIONAR A SACOLA</button>"
        "</div></article>"
    )

def render(lista):
    return "".join(card(p, i) for i, p in enumerate(lista))

def carrossel():
    p1 = "<div class='carrossel'><div class='ctit'>JORNAL DE OFERTAS &bull; DROGARIA TOTAL</div>"
    p2 = "<div class='vbox'><iframe src='https://www.youtube.com/embed/OheBqPHgUr8' title='Jornal de Ofertas Drogaria Total' frameborder='0' allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share' allowfullscreen></iframe></div>"
    p3 = "<div class='vlegenda'>Assista ao jornal de ofertas do mes</div></div>"
    return p1 + p2 + p3
@app.route("/")
def index():
    aba = request.args.get("aba", "").strip()
    q = request.args.get("q", "").strip().lower()
    if aba or q:
        lista = [p for p in CATALOGO if (not aba or p["c"] == aba)]
        if q:
            lista = [p for p in lista if q in p["n"].lower() or q in p["f"].lower()]
        tit = aba if aba else ("Busca: " + request.args.get("q", ""))
        c = "<div class='mt'>" + str(len(lista)) + " produtos em " + tit + "</div>"
        c = c + "<div class='grid'>" + render(lista) + "</div>"
        return PAGINA.replace("__PILLS__", pills(aba)).replace("__CONTEUDO__", c).replace("__Q__", request.args.get("q", "")).replace("__LOGO__", LOGO_TOTAL).replace("__ARTEF__", ARTE_SORTE)
    return home()

def pills(at):
    p = "<a class='pl " + ("on" if not at else "") + "' href='/'>Inicio</a>"
    for a in ABAS:
        if not any(x["c"] == a for x in CATALOGO):
            continue
        p = p + "<a class='pl " + ("on" if at == a else "") + "' href='/?aba=" + urllib.parse.quote_plus(a) + "'>" + a + "</a>"
    return p

