def home():
    # Letreiro: arte oficial da campanha no topo
    b1 = "<div class='letreiro'><img src='" + ARTE_SORTE + "' alt='Drogaria Total - Sorte Real na Total - Especial 30 Anos'></div>"
    # Destaque de vantagem da compra online
    b2 = DESTAQUE
    # Carrossel automatico do Jornal de Ofertas
    b3 = "<div class='sec'><div class='stit'>Jornal de Ofertas</div>"
    b4 = "<div class='ssub'>As ofertas do mes - paginas girando automaticamente</div>"
    b5 = carrossel()
    b6 = "</div>"
    # Abas de categoria
    b7 = "<div class='stit'>Escolha uma categoria</div>"
    b8 = "<div class='cats'>"
    for a in ABAS:
        if not any(x["c"] == a for x in CATALOGO):
            continue
        b8 = b8 + "<a class='cat' href='/?aba=" + urllib.parse.quote_plus(a) + "'><span class='cn'>" + a + "</span></a>"
    b9 = "</div>"
    b10 = SELOS
    return PAGINA.replace("__PILLS__", pills("")).replace("__CONTEUDO__", b1 + b2 + b3 + b4 + b5 + b6 + b7 + b8 + b9 + b10).replace("__Q__", "").replace("__LOGO__", LOGO_TOTAL).replace("__ARTEF__", ARTE_SORTE)
def pg_aba(titulo, lista):
    c1 = "<div class='cvolta'><a href='/'>&#8592; Voltar as categorias</a></div>"
    c2 = "<div class='stit'>" + titulo + "</div>"
    c3 = "<div class='mt'>" + str(len(lista)) + " produtos</div>"
    c4 = "<div class='grid'>" + render(lista) + "</div>"
    return PAGINA.replace("__PILLS__", pills(titulo)).replace("__CONTEUDO__", c1 + c2 + c3 + c4).replace("__Q__", "").replace("__LOGO__", LOGO_TOTAL).replace("__ARTEF__", ARTE_SORTE)

